mapper.select:
SELECT sc.*, u.nick_name as userNickName, ud.sale_id as salesId FROM tb_sync_contrast sc LEFT JOIN tb_user u ON sc.user_id = u.id left join tb_user_details ud on ud.user_id = sc.user_id
and (u.username like CONCAT('%', #{bo.userNickName}, '%') or u.nick_name like CONCAT('%', #{bo.userNickName}, '%') or u.phone like CONCAT('%', #{bo.userNickName}, '%'))
and ud.sale_id = #{bo.userSalesID}
and sc.create_date >= #{bo.startTime}
and sc.create_date <= #{bo.endTime}
order by sc.id desc
